extern printf(fmt: string, ...);

frame main() ret int {
    local a: int = 10;
    local b: int = 3;

    # Basic arithmetic
    printf("a = %d, b = %d\n", a, b);
    printf("a + b = %d\n", a + b);   # Addition: 13
    printf("a - b = %d\n", a - b);   # Subtraction: 7
    printf("a * b = %d\n", a * b);   # Multiplication: 30
    printf("a / b = %d\n", a / b);   # Division: 3 (integer division!)
    printf("a %% b = %d\n", a % b);  # Modulo (remainder): 1

    # Negative numbers
    local c: int = -5;
    printf("-5 = %d\n", c);
    printf("Absolute: %d\n", -c);    # Unary minus: 5

    # Float division (for decimals)
    local x: float = 10.0;
    local y: float = 3.0;
    printf("10.0 / 3.0 = %.4f\n", x / y);  # 3.3333

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local a: int = 10;
    local b: int = 20;
    local c: int = 10;

    printf("a = %d, b = %d, c = %d\n\n", a, b, c);

    # Equality
    printf("a == b: %d\n", a == b);   # 0 (false)
    printf("a == c: %d\n", a == c);   # 1 (true)
    printf("a != b: %d\n", a != b);   # 1 (true)

    # Relational
    printf("a < b: %d\n", a < b);     # 1 (true)
    printf("a > b: %d\n", a > b);     # 0 (false)
    printf("a <= c: %d\n", a <= c);   # 1 (true)
    printf("b >= a: %d\n", b >= a);   # 1 (true)

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local a: bool = true;
    local b: bool = false;

    printf("a = true, b = false\n\n");

    # AND: both must be true
    printf("a && a: %d\n", a && a);   # 1 (true && true = true)
    printf("a && b: %d\n", a && b);   # 0 (true && false = false)
    printf("b && b: %d\n", b && b);   # 0 (false && false = false)

    # OR: at least one must be true
    printf("a || a: %d\n", a || a);   # 1
    printf("a || b: %d\n", a || b);   # 1
    printf("b || b: %d\n", b || b);   # 0

    # NOT: flips the value
    printf("!a: %d\n", !a);           # 0 (not true = false)
    printf("!b: %d\n", !b);           # 1 (not false = true)

    # Combined example
    local age: int = 25;
    local hasLicense: bool = true;
    local canDrive: bool = age >= 18 && hasLicense;
    printf("Can drive (age >= 18 AND hasLicense): %d\n", canDrive);

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    # Arithmetic precedence: * before +
    local result1: int = 2 + 3 * 4;      # 2 + (3*4) = 14, not 20
    local result2: int = (2 + 3) * 4;    # (2+3) * 4 = 20

    printf("2 + 3 * 4 = %d\n", result1);
    printf("(2 + 3) * 4 = %d\n", result2);

    # Mixed comparison and logic
    local a: int = 5;
    local b: int = 10;
    local c: int = 15;

    # This: a < b && b < c
    # Parses as: (a < b) && (b < c)
    local inRange: bool = a < b && b < c;  # true
    printf("5 < 10 < 15: %d\n", inRange);

    # Be explicit with parentheses!
    local explicit: bool = (a < b) && (b < c);
    printf("Explicit: %d\n", explicit);

    return 0;
}

